var o=[{title:`Čtení poměru`,text:`Interval 1:3 může být 20 sekund úsilí a 60 sekund regenerace, interval 1:1 může být 30 sekund od každého a 2:1 může být 40 sekund práce a 20 sekund lehce. Samotný poměr trénink nepopisuje, dokud neznáte trvání a intenzitu.`},{title:`Dlouhá regenerace pro kvalitu`,text:`Docela dlouhé odpočinky vám pomáhají udržet rychlost nebo výkon během krátkých náročných úseků. Nastavení 1:3 může vyhovovat někomu, kdo cvičí rychlejší běh nebo náročný pohyb a chce se hned neunavit. Velmi intenzivní sprinty mohou potřebovat mnohem víc regenerace než 1:3, aby výkon zůstal vysoký.`},{title:`Stejná nebo krátká regenerace`,text:`Při 1:1 trvají práce a regenerace stejně dlouho. Při 2:1 je regenerace kratší, takže se může únava rychle hromadit. Tyto formáty mohou fungovat u středně náročných okruhů, ale nejsou automaticky lepší pro pokročilé vytrvalostní nebo silové cíle.`},{title:`Přizpůsobte schopnostem a cviku`,text:`Začátečník může 30 sekund rychle chodit a 90 sekund lehce a pak pomalu prodlužovat práci. Trénovaný cyklista může použít delší náročné úseky s velkorysou regenerací. Skokové pohyby často vyžadují větší technickou kontrolu, proto zvolte odpočinek, který udrží vaše přistání dobrá. Pokrok posuzujte podle toho, zda končíte se správnou technikou, odpočinek prodlužte, když ho potřebujete, a neztěžujte každý interval jen proto, abyste zkrátili trénink.`}];var n=[{label:`ACE: navrhování vysoce intenzivních intervalů`,url:`https://www.acefitness.org/continuing-education/certified/may-2021/7844/how-to-use-the-ace-ift-model-to-design-effective-hiit-workouts/`},{label:`CDC: měření intenzity aktivity a test mluvení`,url:`https://www.cdc.gov/physicalactivity/basics/measuring/index.html`},{label:`CDC: doporučení k fyzické aktivitě dospělých`,url:`https://www.cdc.gov/physical-activity-basics/guidelines/adults.html`}];var a={sections:o,sources:n};export{a as default,o as sections,n as sources};